    fn saxon_durations() {
        assert_eq!(
            parse_saxon_duration("398.5ms").unwrap(),
            Duration::from_micros(398_500)
        );
        assert_eq!(
            parse_saxon_duration("1.2035s (1203.5ms)").unwrap(),
            Duration::from_micros(1_203_500)
        );
        assert_eq!(
            parse_saxon_duration("1m 2.5s (62500.0ms)").unwrap(),
            ms(62_500)
        );
        assert_eq!(
            parse_saxon_duration("9.5E-4ms").unwrap(),
            Duration::from_nanos(950)
        );
        for bad in ["", "12", "12s", "-1.0ms", "NaNms", "1s (12)"] {
            assert!(parse_saxon_duration(bad).is_err(), "{bad:?}");
        }
    }

    #[test]
    fn saxon_timings_of_a_directory_run() {
        let stderr = "SaxonJ-HE 12.10 from Saxonica\nJava version 21.0.12.1\nUsing parser x\nStylesheet compilation time: 400.0ms\nProcessing file:/a/c00001.xml\nBuilding tree for file:/a/c00001.xml using class net.sf.saxon.tree.tiny.TinyBuilder\nTree built in 1.0ms\nTree size: 205 nodes, 784 characters, 12 attributes\nExecution time: 50.5ms\nMemory used: 68Mb\nProcessing file:/a/c00002.xml\nError at char 3 in expression in xsl:value-of/@select on line 5 column 6 of x.xslt:\n  FORG0001  Cannot convert string \"x\" to xs:decimal\nWhile processing c00002.xml: Cannot convert\nProcessing file:/a/c00003.xml\nExecution time: 1.5005s (1500.5ms)\n1 transformation failed\n";
        assert_eq!(
            parse_saxon_timings(stderr).unwrap(),
            SaxonTimings {
                compile: ms(400),
                execution: ms(1551),
                processed: 3,
                failed: 1
            }
        );
        // With -threads: an exception per thread, no summary line.
        let threaded = "Stylesheet compilation time: 1.0ms\nProcessing file:/a/c00001.xml\nProcessing file:/a/c00002.xml\nWhile processing c00001.xml: Cannot convert\nWhile processing c00002.xml: A sequence\nnet.sf.saxon.s9api.SaxonApiException: 2 transformations failed\n\tat net.sf.saxon.Transform$TransformThread.run(Transform.java:278)\nCaused by: net.sf.saxon.trans.XPathException: 2 transformations failed\n";
        let timings = parse_saxon_timings(threaded).unwrap();
        assert_eq!((timings.processed, timings.failed), (2, 2));
        // The summary of a run without -threads must agree with the documents.
        assert!(
            parse_saxon_timings("Stylesheet compilation time: 1.0ms\n2 transformations failed\n")
                .is_err()
        );
        assert!(parse_saxon_timings("Processing file:/a\n").is_err());
        assert!(
            parse_saxon_timings(
                "Stylesheet compilation time: 1.0ms\nStylesheet compilation time: 1.0ms\n"
            )
            .is_err()
        );
        assert!(
            parse_saxon_timings("Stylesheet compilation time: 1.0ms\nExecution time: soon\n")
                .is_err()
        );
    }

