    fn run(tool: Tool, threads: usize, walls: &[u64], rss: u64, outcome: Outcome) -> ToolRun {
        ToolRun {
            tool,
            threads,
            samples: walls
                .iter()
                .map(|w| Sample {
                    wall: ms(*w),
                    user: ms(*w),
                    system: ms(1),
                    peak_rss_kib: rss,
                    in_jvm: (tool == Tool::Saxon && threads == 1).then(|| ms(*w / 2)),
                })
                .collect(),
            outcome,
        }
    }

    fn report() -> Report {
        let summary = Outcome::Engine(Summary {
            documents: 100,
            valid: 10,
            invalid: 85,
            errors: 5,
        });
        let saxon = Outcome::Saxon { failed: 5 };
        Report {
            machine: Machine {
                date: "2026-11-08".to_owned(),
                commit: "0123456".to_owned(),
                cpu: "Some CPU".to_owned(),
                logical_cpus: 8,
                cores: Some(4),
                memory_kib: 16 * 1024 * 1024,
                os: "Some OS".to_owned(),
                kernel: "6.1".to_owned(),
                rustc: "rustc 1.99.1".to_owned(),
                java: "openjdk 21".to_owned(),
                saxon: "12.10".to_owned(),
                cli: "einvoice-validate 0.2.0".to_owned(),
                load_before: "0.10 0.20 0.30".to_owned(),
                load_after: "0.40 0.50 0.60".to_owned(),
            },
            runs: 3,
            threads: vec![1],
            targets: vec![
                TargetRun {
                    key: "cen-ubl",
                    title: "CEN UBL",
                    documents: 100,
                    stylesheets: 1,
                    schema: Some("ubl-2.1".to_owned()),
                    max_depth: Some(1024),
                    runs: vec![
                        run(Tool::Engine, 1, &[500, 400, 600], 20 * 1024, summary),
                        run(
                            Tool::EngineSameWork,
                            1,
                            &[300, 300, 300],
                            10 * 1024,
                            summary,
                        ),
                        run(Tool::Saxon, 1, &[1500, 1400, 1600], 300 * 1024, saxon),
                    ],
                },
                TargetRun {
                    key: "cen-cii",
                    title: "CEN CII",
                    documents: 50,
                    stylesheets: 2,
                    schema: Some("cii-d16b".to_owned()),
                    max_depth: None,
                    runs: vec![
                        run(Tool::Engine, 1, &[100, 100, 100], 10 * 1024, summary),
                        run(Tool::Saxon, 1, &[1000, 1000, 1000], 200 * 1024, saxon),
                    ],
                },
            ],
            latency: Some(Latency {
                document: "example.xml".to_owned(),
                bytes: 5790,
                runs: vec![
                    run(Tool::Engine, 1, &[40, 42, 41], 12 * 1024, summary),
                    run(Tool::Saxon, 1, &[800, 900, 850], 150 * 1024, saxon),
                ],
            }),
        }
    }

    #[test]
    fn markdown_tables() {
        let text = markdown(&report());
        for expected in [
            "Measured on 2026-11-08 at commit `0123456`: 3 runs",
            "| CPU | Some CPU (8 logical CPUs, 4 physical cores) |",
            "| Memory | 16.0 GiB |",
            "### Whole corpus, 1 thread",
            "| CEN UBL | 100 | 1 | 0.500 s (0.400–0.600) | 0.300 s (0.300–0.300) | 1.50 s (1.40–1.60) | 0.750 s (0.700–0.800) | 3.0× | 5.0× | 2.5× |",
            "| CEN CII | 50 | 2 | 0.100 s (0.100–0.100) | (same run) | 1.00 s (1.00–1.00) | 0.500 s (0.500–0.500) | 10× | 10× | 5.0× |",
            "| **All** | **150** | **3** | **0.600 s** | **0.400 s** | **2.50 s** | **1.25 s** | **4.2×** | **6.2×** | **3.1×** |",
            "| CEN UBL | 200 | 66.7 | 0.501 s | 0.301 s | 1.50 s | 20.0 MiB | 10.0 MiB | 300 MiB | 15× |",
            "| CEN CII | 500 | 50.0 | 0.101 s | (same run) | 1.00 s | 10.0 MiB | (same run) | 200 MiB | 20× |",
            "| CEN UBL | 10 / 85 / 5 | 5 of 100 | 5 of 100 |",
            "| CEN CII | 10 / 85 / 5 | 5 of 100 | 5 of 100 |",
            "`example.xml` (5790 bytes)",
            "| einvoice-validate (built-in `cen-ubl`, with the UBL 2.1 schema) | 41.0 ms (40.0–42.0) | 42.0 ms | 12.0 MiB |",
            "| Saxon-HE | 850 ms (800–900) | 851 ms | 150 MiB |",
            "| Saxon-HE, JVM start excluded (`-t`: compilation and execution) | 425 ms (400–450) | | |",
        ] {
            assert!(text.contains(expected), "missing {expected:?} in:\n{text}");
        }
    }

    /// On several threads, where Saxon-HE's own timings are not given, the
    /// whole-corpus table still ends with the totals of the other columns.
    #[test]
    fn totals_on_several_threads() {
        let summary = Outcome::Engine(Summary {
            documents: 100,
            valid: 10,
            invalid: 85,
            errors: 5,
        });
        let saxon = Outcome::Saxon { failed: 5 };
        let mut report = report();
        report.threads = vec![1, 8];
        report.targets[0].runs.extend([
            run(Tool::Engine, 8, &[100, 90, 110], 30 * 1024, summary),
            run(Tool::EngineSameWork, 8, &[80, 80, 80], 20 * 1024, summary),
            run(Tool::Saxon, 8, &[700, 600, 800], 400 * 1024, saxon),
        ]);
        report.targets[1].runs.extend([
            run(Tool::Engine, 8, &[50, 50, 50], 10 * 1024, summary),
            run(Tool::Saxon, 8, &[500, 500, 500], 200 * 1024, saxon),
        ]);
        let text = markdown(&report);
        let eight = text
            .split_once("### Whole corpus, 8 threads")
            .map(|(_, rest)| rest)
            .unwrap();
        for expected in [
            "| CEN UBL | 100 | 1 | 0.100 s (0.090–0.110) | 0.080 s (0.080–0.080) | 0.700 s (0.600–0.800) | 7.0× | 8.8× |",
            "| **All** | **150** | **3** | **0.150 s** | **0.130 s** | **1.20 s** | **8.0×** | **9.2×** |",
        ] {
            assert!(
                eight.contains(expected),
                "missing {expected:?} in:\n{eight}"
            );
        }
        assert!(text.contains(
            "| **All** | **150** | **3** | **0.600 s** | **0.400 s** | **2.50 s** | **1.25 s** |"
        ));
    }

